import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Table, Alert, Spin } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import NotificationActions from '../../redux/notifications/actions'

const { resetNotificationCore, getPublishedTrigger } = NotificationActions

class PublishedTriggerDetail extends React.Component {
    state = {
      loader: true,
      dataPublishedTrigger: {}
    }
    back = () => {
      const { history } = this.props
      history.push('/notifications')
    }
    componentWillReceiveProps (nextProps) {
      const { dataPublishedTrigger, gePublishedTriggerStatus } = nextProps.Notifications
      if (gePublishedTriggerStatus !== '') {
        this.setState({
          gePublishedTriggerStatus,
          dataPublishedTrigger,
          loader: false
        })
      }
    }
    componentDidMount () {
      const querySearch = QueryString.parse(this.props.location.search)
      this.props.getPublishedTrigger(querySearch)
    }
    componentWillUnmount () {
      this.props.resetNotificationCore()
    }
    onCloseAlert = () => {
      this.props.resetNotificationCore()
      this.setState({ gePublishedTriggerStatus: '' })
    }
    convertExpression = expressions => {
      let mergeExpression = ''
      if (expressions.length > 0) {
        expressions.forEach(element => {
          mergeExpression += JSON.stringify(element)
        })
      }
      this.setState({ expressions: mergeExpression })
    }
    render () {
      const { dataPublishedTrigger, expressions } = this.state
      const columns = [
        {
          dataIndex: 'name',
          width: 150
        }, {
          dataIndex: 'value'
        }
      ]
      let dataInfo = []
      let count = 0
      for (let key in dataPublishedTrigger) {
        if (key === 'expression') {
          this.convertExpression(dataPublishedTrigger['expression'])
          delete dataPublishedTrigger['expression']
        }
        let titleReplace = key.replace(/_/gi, ' ')
        let upperCase = titleReplace.charAt(0).toUpperCase() + titleReplace.substr(1)
        dataInfo = [...dataInfo, {
          key: count,
          name: <strong>{dataPublishedTrigger[key] !== undefined && upperCase}</strong>,
          value: dataPublishedTrigger[key] !== undefined && dataPublishedTrigger[key]
        }]
        count++
      }
      if (dataInfo.length > 0) {
        dataInfo = [...dataInfo, {
          key: 'expression',
          name: <strong>Expression</strong>,
          value: expressions
        }]
      }
      return (
        <LayoutContentWrapper>
          {
            (this.state.gePublishedTriggerStatus !== '' && this.state.gePublishedTriggerStatus !== undefined && this.state.gePublishedTriggerStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.gePublishedTriggerStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          <LayoutContent>
            <Row>
              <Col>
                <Button onClick={this.back}>Back</Button>
              </Col>
              <Col>
                <Spin spinning={this.state.loader}>
                  <Table
                    pagination={false}
                    showHeader={false}
                    columns={columns}
                    dataSource={dataInfo}
                  />
                </Spin>
              </Col>
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      )
    }
}

export default connect(
  state => ({
    Notifications: state.Notifications
  }),
  { getPublishedTrigger, resetNotificationCore }
)(PublishedTriggerDetail)
